basic.forever(function () {
    if (pins.analogReadPin(AnalogPin.P0) >= 512) {
        pins.servoWritePin(AnalogPin.P1, 135)
        pins.servoSetPulse(AnalogPin.P2, 1800)
    } else {
        pins.servoWritePin(AnalogPin.P1, 45)
        pins.servoSetPulse(AnalogPin.P2, 1000)
    }
    basic.pause(20)
})
